      "name": "test_upper_bound",
      "source": "def test_upper_bound(run, x):
    # For n circles, maximum regions is n^2 - n + 2 (if all pairs intersect in two points and no three intersect at same point).
    # Since n <= 3, that gives at most 8 regions.
    out = run(x)
    regions = int(out.strip())
    n = int(x.split('\n')[0])
    max_regions = n * n - n + 2
    assert regions <= max_regions, f'for n={n}, regions cannot exceed {max_regions}'"
    },
