def test_output_format(run, x):
    out = run(x)
    assert out in ("YES\n", "NO\n"), f"Output must be exactly YES or NO with newline, got {repr(out)}"


def test_already_symmetric(run, x):
    # If the grid is already symmetric, answer must be YES.
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    grid = lines[1:]
    symmetric = True
    for i in range(H):
        for j in range(W):
            if grid[i][j] != grid[H-1-i][W-1-j]:
                symmetric = False
                break
        if not symmetric:
            break
    if symmetric:
        out = run(x)
        assert out == "YES\n", f"Grid is already symmetric, must output YES, got {repr(out)}"


def test_single_row_palindrome(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    if H == 1:
        row = lines[1]
        is_pal = row == row[::-1]
        out = run(x)
        if is_pal:
            assert out == "YES\n", f"Single row palindrome, must output YES, got {repr(out)}"
        else:
            # Not necessarily NO, because columns can be swapped.
            # But after any column swaps, the row becomes a permutation of itself.
            # A palindrome is possible iff multiset of letters can form a palindrome.
            from collections import Counter
            cnt = Counter(row)
            odd = sum(v % 2 for v in cnt.values())
            possible = odd <= 1
            if possible:
                # Actually, with one row, column swaps just permute the row.
                # If multiset allows palindrome, we can arrange columns to make it symmetric.
                # Because symmetry for H=1 means row[j]==row[W-1-j] for all j.
                # That's exactly a palindrome.
                # So answer must be YES if possible, else NO.
                if out != "YES\n":
                    # Check if our reasoning is wrong by brute force for small W.
                    if W <= 8:
                        from itertools import permutations
                        for perm in permutations(range(W)):
                            perm_row = ''.join(row[p] for p in perm)
                            if perm_row == perm_row[::-1]:
                                # found a permutation making palindrome
                                assert out == "YES\n", f"W={W}, row={row}, permutation exists, must be YES, got {repr(out)}"
                                return
                        # no permutation works
                        assert out == "NO\n", f"W={W}, row={row}, no permutation makes palindrome, must be NO, got {repr(out)}"
                # else out is YES, which is fine
            else:
                # impossible
                if out != "NO\n":
                    # double-check with brute force for small W
                    if W <= 8:
                        from itertools import permutations
                        for perm in permutations(range(W)):
                            perm_row = ''.join(row[p] for p in perm)
                            if perm_row == perm_row[::-1]:
                                # should not happen
                                pass
                        # none found
                        assert out == "NO\n", f"W={W}, row={row}, palindrome impossible, must be NO, got {repr(out)}"


def test_single_column_palindrome(run, x):
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    if W == 1:
        col = ''.join(lines[i+1][0] for i in range(H))
        is_pal = col == col[::-1]
        out = run(x)
        if is_pal:
            assert out == "YES\n", f"Single column palindrome, must output YES, got {repr(out)}"
        else:
            from collections import Counter
            cnt = Counter(col)
            odd = sum(v % 2 for v in cnt.values())
            possible = odd <= 1
            if possible:
                # similar reasoning as for single row
                if out != "YES\n":
                    if H <= 8:
                        from itertools import permutations
                        for perm in permutations(range(H)):
                            perm_col = ''.join(col[p] for p in perm)
                            if perm_col == perm_col[::-1]:
                                assert out == "YES\n", f"H={H}, col={col}, permutation exists, must be YES, got {repr(out)}"
                                return
                        assert out == "NO\n", f"H={H}, col={col}, no permutation makes palindrome, must be NO, got {repr(out)}"
            else:
                if out != "NO\n":
                    if H <= 8:
                        from itertools import permutations
                        for perm in permutations(range(H)):
                            perm_col = ''.join(col[p] for p in perm)
                            if perm_col == perm_col[::-1]:
                                pass
                        assert out == "NO\n", f"H={H}, col={col}, palindrome impossible, must be NO, got {repr(out)}"


def test_letter_count_parity(run, x):
    # For the whole grid, after any row/col swaps, symmetry requires that
    # each letter appears an even number of times, except possibly one letter when H*W is odd.
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    from collections import Counter
    cnt = Counter(''.join(lines[1:]))
    odd = sum(v % 2 for v in cnt.values())
    total_cells = H * W
    possible_by_parity = odd <= (total_cells % 2)  # if total cells odd, at most one odd count
    out = run(x)
    if not possible_by_parity:
        # impossible to make symmetric by any permutation
        assert out == "NO\n", f"Letter count parity impossible, must output NO, got {repr(out)}"


def test_small_bruteforce(run, x):
    # For H,W <= 3, brute-force all row/column permutations to verify answer.
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    if H > 3 or W > 3:
        return  # skip large grids
    grid = [list(row) for row in lines[1:]]
    from itertools import permutations
    possible = False
    for row_perm in permutations(range(H)):
        for col_perm in permutations(range(W)):
            ok = True
            for i in range(H):
                for j in range(W):
                    a = grid[row_perm[i]][col_perm[j]]
                    b = grid[row_perm[H-1-i]][col_perm[W-1-j]]
                    if a != b:
                        ok = False
                        break
                if not ok:
                    break
            if ok:
                possible = True
                break
        if possible:
            break
    out = run(x)
    if possible:
        assert out == "YES\n", f"Brute‑force says YES, got {repr(out)}"
    else:
        assert out == "NO\n", f"Brute‑force says NO, got {repr(out)}"


def test_row_pairing_condition(run, x):
    # If answer is YES, then rows can be partitioned into pairs (and maybe one middle row)
    # such that each pair can be placed symmetrically.
    # This is a necessary condition.
    lines = x.strip().split('\n')
    H, W = map(int, lines[0].split())
    out = run(x)
    if out == "YES\n":
        rows = lines[1:]
        # For each row, compute its multiset of letters.
        from collections import Counter
