    H, W = map(int, lines[0].split())
    if H * W > 20:  # brute force only for very small grids
        return
    grid = [list(row) for row in lines[1:]]
    # Find S and T
    S = T = None
    leaves = []
    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                S = (i, j)
            elif grid[i][j] == 'T':
                T = (i, j)
            elif grid[i][j] == 'o':
                leaves.append((i, j))
    n = len(leaves)
    # Try all subsets of leaves to remove
    best = float('inf')
    from itertools import combinations
    # Function to check if frog can reach T
    def can_reach(removed_set):
        # BFS on leaf graph
        from collections import deque
        visited = set()
        q = deque([S])
        visited.add(S)
        while q:
            r, c = q.popleft()
            if (r, c) == T:
                return True
            # Same row leaves
            for cc in range(W):
                pos = (r, cc)
                if grid[r][cc] in ('o','S','T') and pos not in removed_set:
                    if pos not in visited:
                        visited.add(pos)
                        q.append(pos)
            # Same column leaves
            for rr in range(H):
                pos = (rr, c)
                if grid[rr][c] in ('o','S','T') and pos not in removed_set:
                    if pos not in visited:
                        visited.add(pos)
                        q.append(pos)
        return False
    # If S and T are same row/col and no leaves between, answer must be -1
    si, sj = S
    ti, tj = T
    if si == ti or sj == tj:
        direct = True
        if si == ti:
            for col in range(min(sj, tj)+1, max(sj, tj)):
                if grid[si][col] == 'o':
                    direct = False
                    break
        if sj == tj:
            for row in range(min(si, ti)+1, max(si, ti)):
                if grid[row][sj] == 'o':
                    direct = False
                    break
        if direct:
            # frog can jump directly
            assert run(x).strip() == '-1'
            return
    for k in range(n+1):
        for comb in combinations(leaves, k):
            removed = set(comb)
            if not can_reach(removed):
                best = min(best, k)
                break  # found minimal for this k
        if best != float('inf'):
            break
    expected = -1 if best == float('inf') else best
    out = run(x).strip()
    if out == '-1':
        assert expected == -1
    else:
        assert int(out) == expected

def test_answer_integer(run, x):
    out = run(x).strip()
    # Must be integer
    if out == '-1':
        return
    try:
        int(out)
    except ValueError:
        assert False, f'Output not integer: {out}'

