    if out == '-1':
        return
    b = int(out)
    n = int(x.split('\n')[0])
    s = int(x.split('\n')[1])
    if b == n + 1:
        assert s == n

def test_f_decreases_with_b_for_b_gt_n(run, x):
    out = run(x).strip()
    if out == '-1':
        return
    b = int(out)
    n = int(x.split('\n')[0])
    s = int(x.split('\n')[1])
    if b > n:
        assert s == n

def test_no_solution_if_s_greater_than_n(run, x):
    n = int(x.split('\n')[0])
    s = int(x.split('\n')[1])
    if s > n:
        out = run(x).strip()
        assert out == '-1'

