    n = int(x.strip())
    ans = int(run(x).strip())
    # trivial upper bound: each of n digits can be one of 4 values
    # so at most 4^n distinct representations, but many give same sum
    # hence answer <= 4^n
    import math
    if n <= 100:  # avoid huge exponent overflow
        bound = 4 ** n
    else:
        # use logarithm to compare
        if ans > 0:
            # if ans > 4^n, then log2(ans) > n * 2
            # but ans fits in 64 bits? Not necessarily, but 4^n huge.
            # We'll just skip for large n because bound is astronomical
            return
    if n <= 100:
        assert ans <= bound


