def test_small_bruteforce(run, x):
    # Only run brute-force for N ≤ 5, else skip.
    lines = x.strip().split('\n')
    N = int(lines[0])
    if N > 5:
        return  # too big for brute-force
    S = lines[1]
    from itertools import product
    chars = {'A', 'B', 'C'}
    def next_strings(t):
        res = set()
        for i in range(len(t)-1):
            if t[i] != t[i+1]:
                diff = (chars - {t[i], t[i+1]}).pop()
                new_t = t[:i] + diff + t[i+2:]
                res.add(new_t)
        return res
    reachable = {S}
    frontier = {S}
    while frontier:
        new = set()
        for t in frontier:
            for nt in next_strings(t):
                if nt not in reachable:
                    reachable.add(nt)
                    new.add(nt)
        frontier = new
    expected = len(reachable)
    ans = int(run(x).strip())
    assert ans == expected

def test_output_non_negative_integer(run, x):
    out = run(x).strip()
    val = int(out)
    assert val >= 0

def test_output_modulo(run, x):
    out = run(x).strip()
    val = int(out)
    MOD = 10**9 + 7
    assert 0 <= val < MOD

def test_at_least_one(run, x):
    out = run(x).strip()
    val = int(out)
    assert val >= 1  # at least the original string is reachable

def test_upper_bound_3_pow_N(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    out = run(x).strip()
    val = int(out)
    # The total number of possible strings over {A,B,C} of any length ≤ N
    # is at most 3^N + 3^{N-1} + ... + 3^0 < 3^{N+1}.
    # We'll check val < 3**(N+1) to avoid large exponent for big N.
    # Compute 3**(N+1) carefully for N up to 10^6 but test only for moderate N.
    if N <= 20:  # safe to compute
        bound = 3 ** (N + 1)
        assert val < bound
    else:
        # For large N, use log check.
        import math
        if val > 0:
            log_val = math.log(val)
            log_bound = (N + 1) * math.log(3)
            assert log_val < log_bound + 1e-9

def test_single_character_input(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    S = lines[1]
    if N == 1:
        out = run(x).strip()
        val = int(out)
        assert val == 1  # only the original string

def test_two_identical_characters(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    S = lines[1]
    if N == 2 and S[0] == S[1]:
        out = run(x).strip()
        val = int(out)
        assert val == 1  # cannot perform any operation

def test_two_different_characters(run, x):
    lines = x.strip().split('\n')
    N = int(lines[0])
    S = lines[1]
    if N == 2 and S[0] != S[1]:
        out = run(x).strip()
        val = int(out)
        # Operation possible: replace first with third char, remove second.
        # Result is a single character (the third one).
        # Reachable strings: original length‑2 and the single‑char result.
        assert val == 2

def test_permutation_symmetry(run, x):
    # If we permute A,B,C consistently in the input, answer should stay same.
    # Only run for N ≤ 6 to avoid heavy recomputation.
    lines = x.strip().split('\n')
    N = int(lines[0])
    if N > 6:
        return
    S = lines[1]
    perm = {'A':'B','B':'C','C':'A'}
    S2 = ''.join(perm[ch] for ch in S)
    inp2 = f"{N}\n{S2}\n"
    # Cannot call run again. So we cannot directly compare.
    # Instead we check that the answer for S is the same as for S2
    # by using brute‑force for these small inputs.
    # We already have brute‑force code from test_small_bruteforce.
    def brute(S):
        from itertools import product
        chars = {'A','B','C'}
        def next_strings(t):
            res=set()
            for i in range(len(t)-1):
                if t[i]!=t[i+1]:
                    diff=(chars-{t[i],t[i+1]}).pop()
                    new_t=t[:i]+diff+t[i+2:]
                    res.add(new_t)
            return res
        reachable={S}
        frontier={S}
        while frontier:
            new=set()
            for t in frontier:
                for nt in next_strings(t):
                    if nt not in reachable:
                        reachable.add(nt)
                        new.add(nt)
            frontier=new
        return len(reachable)
    val1 = brute(S)
    val2 = brute(S2)
    assert val1 == val2

def test_reversal_symmetry(run, x):
    # Reversing the string should give same answer.
    # Only for small N where we can brute‑force both.
    lines = x.strip().split('\n')
    N = int(lines[0])
    if N > 6:
        return
    S = lines[1]
    S_rev = S[::-1]
    def brute(S):
        from itertools import product
        chars = {'A','B','C'}
        def next_strings(t):
            res=set()
            for i in range(len(t)-1):
                if t[i]!=t[i+1]:
                    diff=(chars-{t[i],t[i+1]}).pop()
                    new_t=t[:i]+diff+t[i+2:]
                    res.add(new_t)
            return res
        reachable={S}
        frontier={S}
        while frontier:
            new=set()
            for t in frontier:
                for nt in next_strings(t):
                    if nt not in reachable:
                        reachable.add(nt)
                        new.add(nt)
            frontier=new
        return len(reachable)
    val1 = brute(S)
    val2 = brute(S_rev)
    assert val1 == val2

def test_output_is_non_negative_integer(run, x):
    out = run(x).strip()
    val = int(out)
    assert val >= 0

def test_answer_le_n_times_m(run, x):
    n, m = map(int, x.strip().split())
    ans = int(run(x).strip())
    assert ans <= n * m

def test_answer_le_perm_7(run, x):
    import math
    n, m = map(int, x.strip().split())
    a = (0 if n == 1 else len(oct(n-1).split('o')[-1]))
    b = (0 if m == 1 else len(oct(m-1).split('o')[-1]))
    total_digits = a + b
    if total_digits > 7:
        assert int(run(x).strip()) == 0
    else:
        max_possible = math.perm(7, total_digits)
        ans = int(run(x).strip())
        assert ans <= max_possible

def test_answer_zero_when_digits_gt_7(run, x):
    n, m = map(int, x.strip().split())
    a = (0 if n == 1 else len(oct(n-1).split('o')[-1]))
    b = (0 if m == 1 else len(oct(m-1).split('o')[-1]))
    if a + b > 7:
        assert int(run(x).strip()) == 0

def test_brute_small(run, x):
    n, m = map(int, x.strip().split())
    if n * m > 10**6:
        return
    ans = int(run(x).strip())
    correct = 0
    for h in range(n):
        for mm in range(m):
            s = format(h, '07d') + format(mm, '07d')
            if len(set(s)) == len(s):
                correct += 1
    assert ans == correct

def test_answer_integer(run, x):
    out = run(x).strip()
    int(out)

def test_answer_non_negative(run, x):
    ans = int(run(x).strip())
    assert ans >= 0

def test_answer_below_possible_pairs(run, x):
    n, m = map(int, x.strip().split())
    a = (0 if n == 1 else len(oct(n-1).split('o')[-1]))
    b = (0 if m == 1 else len(oct(m-1).split('o')[-1]))
    total_digits = a + b
    if total_digits <= 7:
        import math
        max_pairs = math.perm(7, total_digits)
        ans = int(run(x).strip())
        assert ans <= max_pairs

def test_answer_at_most_7_when_n_or_m_is_1(run, x):
    n, m = map(int, x.strip().split())
    if n == 1 or m == 1:
        ans = int(run(x).strip())
        assert ans <= 7

def test_answer_consistent_with_digit_lengths(run, x):
    n, m = map(int, x.strip().split())
    a = (0 if n == 1 else len(oct(n-1).split('o')[-1]))
    b = (0 if m == 1 else len(oct(m-1).split('o')[-1]))
    total_digits = a + b
    if total_digits > 7:
        assert int(run(x).strip()) == 0
    else:
        ans = int(run(x).strip())
        assert ans <= 7**total_digits

