def test_brute_force_small(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    if n > 5:  # too big for brute force
        return
    c = list(map(int, lines[1].split()))
    # Brute-force all rooted trees? Too complex. Instead, use known condition: we can check if a tree exists via known algorithm: sort c descending, root must be n, and we can try to assign children.
    # Since n <=5 we can brute-force all parent assignments.
