    # Parent must be less than child? Not required. But we can generate all functions p[1..n-1] with p[i] in [0..n-1] and p[i]!=i.
    # Also ensure no cycles.
    # This is heavy but n <=5 so at most 5^4 = 625 assignments.
    def is_tree(parent):
        # parent[root] = root
        # check connectivity and no cycles
        visited = [False]*n
        for i in range(n):
            if visited[i]:
                continue
            stack = []
            cur = i
            while not visited[cur]:
                visited[cur] = True
                stack.append(cur)
                if parent[cur] == cur:
                    break
                cur = parent[cur]
                if cur in stack:
                    return False
        # all nodes must be reachable from root? Not necessarily, but tree must be connected.
        # root is node with parent itself.
        roots = [i for i in range(n) if parent[i]==i]
        if len(roots)!=1:
            return False
        root = roots[0]
        # dfs to check connectivity
        visited = [False]*n
        stack=[root]
        while stack:
            u=stack.pop()
            if visited[u]:
                continue
            visited[u]=True
            for v in range(n):
                if parent[v]==u and v!=u:
                    stack.append(v)
        if not all(visited):
            return False
        # check subtree sizes
        # compute size via recursion
        def compute_size(u):
            sz = 1
            for v in range(n):
                if parent[v]==u and v!=u:
                    sz += compute_size(v)
            return sz
        for i in range(n):
            if compute_size(i) != c[i]:
                return False
        # check internal node has at least two sons
        for i in range(n):
            children = [v for v in range(n) if parent[v]==i and v!=i]
            if len(children) == 1:
                return False
        return True
    possible = False
    # generate all parent arrays
    # parent[0] can be 0..n-1, but we can fix root as node with c = n? Actually root must have c=n.
    root_candidates = [i for i in range(n) if c[i]==n]
    if not root_candidates:
        possible=False
    else:
        for root in root_candidates:
            # generate parent for other nodes
            others = [i for i in range(n) if i!=root]
            for prod in itertools.product(range(n), repeat=len(others)):
                parent = [0]*n
                parent[root]=root
                for idx,node in enumerate(others):
                    parent[node]=prod[idx]
                if is_tree(parent):
                    possible=True
                    break
            if possible:
                break
    expected = 'YES' if possible else 'NO'
    out = run(x).strip()
    assert out == expected, f'For small n, brute force says {expected} but got {out}'

def test_yes_implies_n_in_c(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    c = list(map(int, lines[1].split()))
    out = run(x).strip()
    if out == 'YES':
        assert n in c, 'If answer YES, n must appear in c'

def test_output_length(run, x):
    out = run(x).strip()
