def test_format(run, x):
    out = run(x).strip()
    assert out in ("YES", "NO"), f"Output must be YES or NO, got '{out}'"

def test_trivial_all_unlocked(run, x):
    lines = x.strip().split('\n')
    n_m = list(map(int, lines[0].split()))
    n = n_m[0]
    if n < 1:
        return
    doors = list(map(int, lines[1].split()))
    if all(d == 1 for d in doors):
        out = run(x).strip()
        assert out == "YES", f"All doors already unlocked must be YES, got {out}"

def test_trivial_all_locked(run, x):
    lines = x.strip().split('\n')
    n_m = list(map(int, lines[0].split()))
    n = n_m[0]
    if n < 1:
        return
    doors = list(map(int, lines[1].split()))
    if all(d == 0 for d in doors):
        # not necessarily YES, because toggles might not be possible
        # but we can check that output is either YES or NO (already covered by format test)
        pass

def test_parity_invariant(run, x):
    # For each door controlled by exactly two switches, the parity of toggles of those switches must match door's target.
    # We cannot compute target without solving, but we can check that if a door's two switches are the same (self-loop?) – not possible per spec.
    # Instead, we check that the answer is consistent with a small brute-force on tiny instances.
    # This test will only run brute-force when n,m <= 4.
    lines = x.strip().split('\n')
    n_m = list(map(int, lines[0].split()))
    n, m = n_m
    if n > 4 or m > 4:
        return
    # brute-force all 2^m toggle combinations
    doors = list(map(int, lines[1].split()))
    switches = []
    for i in range(m):
        parts = list(map(int, lines[2 + i].split()))
        switches.append(parts[1:] if parts[0] > 0 else [])
    possible = False
    for mask in range(1 << m):
        state = doors[:]
        for sw in range(m):
            if (mask >> sw) & 1:
                for room in switches[sw]:
                    state[room - 1] ^= 1  # toggle
        if all(s == 1 for s in state):
            possible = True
            break
    out = run(x).strip()
    if possible:
        assert out == "YES", f"Brute-force says YES, got {out}"
    else:
        assert out == "NO", f"Brute-force says NO, got {out}"

def test_switch_with_no_rooms(run, x):
    # A switch that controls zero rooms does nothing.
    # The answer must be same as if that switch were removed.
    # We cannot remove it, but we can check that if all switches control zero rooms and doors are not all unlocked, answer is NO.
    lines = x.strip().split('\n')
    n_m = list(map(int, lines[0].split()))
    n, m = n_m
    doors = list(map(int, lines[1].split()))
    all_zero = True
    for i in range(m):
        parts = list(map(int, lines[2 + i].split()))
        if parts[0] != 0:
            all_zero = False
            break
    if all_zero:
        out = run(x).strip()
        if all(d == 1 for d in doors):
            assert out == "YES", f"All doors unlocked and no switches => YES, got {out}"
        else:
            assert out == "NO", f"Doors not all unlocked and no switches affect anything => NO, got {out}"

def test_door_controlled_by_two_switches(run, x):
    # Spec: each door is controlled by exactly two switches.
    # We can verify that property from input.
    lines = x.strip().split('\n')
    n_m = list(map(int, lines[0].split()))
    n, m = n_m
    cnt = [0] * n
    for i in range(m):
        parts = list(map(int, lines[2 + i].split()))
        for room in parts[1:]:
            cnt[room - 1] += 1
    # This is a sanity check on the input, not on output.
    # But we can assert that if any door has count != 2, input violates spec.
    # However, spec guarantees it, so we just note.
    # We'll instead check that output is YES or NO (already done).
    pass

