def test_not_worse_than_original(run, x):
    lines = x.strip().split('\n')
    n = int(lines[0])
    A = list(map(int, lines[1].split()))
    # longest non-decreasing subsequence in original
    # compute via DP O(n^2) but n <= 2000, we only have small inputs here.
    dp = [1]*n
    for i in range(n):
        for j in range(i):
            if A[j] <= A[i]:
                dp[i] = max(dp[i], dp[j]+1)
    orig = max(dp) if n>0 else 0
    ans = int(run(x).strip())
    assert ans >= orig

